/**
 * The mod over `agent-hub answer`, whose parser and steps have their own tests. A test's sandbox
 * can't run a process, so the CLI is replayed from views.ts, generated by the real thing.
 */
import type { On } from "claude-code";
import { expect, mock, test } from "claude-code/testing";
import type { Engine } from "claude-code/testing";

import { GRILLING, MINE, PLAIN, VIEWS } from "./views";

const BAND = {
  plugin: "answer",
  component: "AbovePrompt",
  props: {
    hasSurvey: false,
    isWorking: false,
    maxRows: 10,
    bodyColumns: 120,
    scroll: { offset: 0, bodyRows: 10 },
    view: {},
  },
} as const;

const PANE = {
  plugin: "answer",
  component: "Pane",
  requestId: "answer",
  props: {
    title: "Answer",
    isFocused: true,
    bodyColumns: 60,
    placement: "dock",
    scroll: { offset: 0, bodyRows: 30 },
    view: {},
  },
} as const;

const RUN = {
  command: "answer",
  args: "",
  origin: { kind: "composer" },
  presentation: { isFullscreen: true, columns: 160 },
} as const;

const PICK_B = { do: "pick", entry: 1 };

/** The CLI, as far as a test walks it: a path through views.ts and one reply left to take. */
function cli() {
  let path: unknown[] | null = null;
  let delivery: { text: string; submit: boolean } | null = null;
  let mtime = 0;
  const view = () => (path ? (VIEWS[JSON.stringify(path)] ?? null) : null);
  const moved = () => {
    mtime += 1;
  };
  return {
    mtime: () => (path ? mtime : null),
    /** What another surface does to the file. */
    step(action: unknown) {
      if (!path) throw new Error("no form");
      path = [...path, action];
      if (!(JSON.stringify(path) in VIEWS)) throw new Error(`views.py: no path ${String(path)}`);
      moved();
      return view();
    },
    deliver(text: string, submit: boolean) {
      delivery = { text, submit };
      moved();
    },
    run(argv: readonly string[], stdin?: string) {
      const verb = argv[2];
      if (verb === "path") return "/forms/session.json\n";
      if (verb === "drop") path = null;
      if (verb === "offer" && stdin !== path?.[0] && VIEWS[JSON.stringify([stdin])]) {
        path = [stdin];
        moved();
      }
      if (verb === "step") this.step(JSON.parse(String(argv[argv.indexOf("--form") + 2])));
      if (verb !== "sync") return `${JSON.stringify(view())}\n`;
      const taken = delivery;
      delivery = null;
      if (taken?.submit) path = null;
      return `${JSON.stringify({ view: view(), delivery: taken })}\n`;
    },
  };
}

type Cli = ReturnType<typeof cli>;

type World = {
  box: string;
  isOpen: boolean;
  submitted: string[];
  hub: Cli;
  clock: ReturnType<typeof mock.clock>;
};

/** Stands in for the engine: the prompt box, the one pane and the band beneath. */
function world(on: On, draft = "", hasHub = true): World {
  const hub = cli();
  const w: World = { box: draft, isOpen: false, submitted: [], hub, clock: mock.clock(on) };
  on("session.id", () => ({ value: "session" }));
  on("process.run", (_, e) => {
    if (!hasHub) throw new Error("cannot start");
    return { value: { exitCode: 0, stdout: hub.run(e.argv, e.init?.stdin), stderr: "" } };
  });
  on("fs.stat", () => {
    const mtimeMs = hub.mtime();
    if (mtimeMs === null) throw new Error("no such file");
    return { value: { kind: "file", size: 0, mtimeMs, isLink: false } };
  });
  on("prompt.read", () => ({ value: { text: w.box, cursor: w.box.length } }));
  on("prompt.fill", (_, e) => {
    w.box = e.text;
    return { isFilled: true };
  });
  on("prompt.submit", (_, e) => {
    w.submitted.push(e.text);
    return { text: e.text };
  });
  on("turn.complete", () => ({ text: "" }));
  on("command.register", () => ({ value: { command: "answer" } }));
  on("session.start", (_, e) => ({ cwd: e.cwd }));
  on("ui.open", () => {
    w.isOpen = true;
    return { value: { isPlaced: true } };
  });
  on("ui.close", () => {
    w.isOpen = false;
    return { value: undefined };
  });
  on("ui.panes", () => ({
    value: w.isOpen
      ? [{ id: "answer", title: "Answer", isShown: true, isFocused: true, isPlaced: true }]
      : [],
  }));
  on("ui.focus", () => ({}));
  on("ui.toast", () => ({ value: undefined }));
  on("ui.log", () => ({ value: undefined }));
  on("ui.render", ($, e) => {
    const { Text } = $.ui.resolve(e);
    return <Text>engine</Text>;
  });
  return w;
}

const start = ($: Engine) =>
  $.session.start({ cwd: "/", surface: "terminal", isInteractive: true });

const ends = ($: Engine, answer: string) =>
  $.turn.complete({ answer, reason: "answer", turnId: "t", durationMs: 1, isAborted: false });

const hint = async ($: Engine) => {
  const band = await $.ui.mount({ ...BAND, surface: "terminal" });
  const found = await band.find({ key: "answer" });
  await band.unmount();
  return found?.text;
};

test("a turn that ends on questions offers the form; the person's next send drops it", async ($, on) => {
  const w = world(on);
  await ends($, GRILLING);
  expect(await hint($)).toContain("Answer 3 questions");
  await $.prompt.submit({ text: "never mind", wait: false, origin: { kind: "composer" } });
  expect(w.hub.mtime()).toBeNull();
  await ends($, PLAIN);
  expect(await hint($)).toBeUndefined();
});

test("a background task's turn leaves the round and its answers alone", async ($, on) => {
  world(on);
  await start($);
  await ends($, GRILLING);
  await $.command.run(RUN);
  const pane = await $.ui.mount({ ...PANE, surface: "terminal" });
  await pane.press({ key: "e1" });
  await pane.input({ key: "field", text: "" });
  await pane.unmount();

  await $.prompt.submit({
    text: "<task-notification>build finished</task-notification>",
    wait: false,
    isMeta: true,
    origin: { kind: "task-notification" },
  });
  await ends($, PLAIN);
  expect(await hint($)).toContain("1 answered");
  // The same round asked again keeps its answers too.
  await ends($, GRILLING);
  expect(await hint($)).toContain("1 answered");
});

test("the band keeps what is drawn beneath it", async ($, on) => {
  world(on);
  await ends($, GRILLING);
  const band = await $.ui.mount({ ...BAND, surface: "terminal" });
  expect(await band.find({ type: "Text", text: /engine/ })).toBeDefined();
  await band.unmount();
});

test("a pick asks for a note, Enter goes on, and the review fills the prompt", async ($, on) => {
  const w = world(on, "and keep it short");
  await ends($, GRILLING);
  const band = await $.ui.mount({ ...BAND, surface: "terminal" });
  await band.press({ key: "answer" });
  await band.unmount();
  expect(w.isOpen).toBe(true);

  const pane = await $.ui.mount({ ...PANE, surface: "terminal" });
  // Q1: B, with a note.
  await pane.press({ key: "e1" });
  await pane.input({ key: "field", text: "but keep the flag" });
  // Q2 has a recommendation and no options: it is the first entry. Enter skips the note.
  expect((await pane.find({ key: "e0" }))?.text).toContain("Yes:");
  await pane.press({ key: "e0" });
  await pane.input({ key: "field", text: "" });
  // Q3's write-in follows its two options.
  await pane.press({ key: "e2" });
  await pane.input({ key: "field", text: "drop it" });
  expect(
    await pane.find({ type: "Text", text: /^Q1: B — but keep the flag\nQ2: yes\nQ3: drop it$/ }),
  ).toBeDefined();
  await pane.press({ key: "fill" });
  await pane.unmount();

  expect(w.box).toBe("Q1: B — but keep the flag\nQ2: yes\nQ3: drop it\n\nand keep it short");
  expect(w.isOpen).toBe(false);
});

test("skip, back and forward move without answering; closing keeps the answers", async ($, on) => {
  world(on);
  await start($);
  await ends($, GRILLING);
  await $.command.run(RUN);
  const pane = await $.ui.mount({ ...PANE, surface: "terminal" });
  await pane.press({ key: "skip" });
  await pane.press({ key: "back" });
  expect(await pane.find({ type: "Text", text: /^Q1 · 1 of 3$/ })).toBeDefined();
  await pane.press({ key: "forward" });
  await pane.press({ key: "e0" });
  await pane.input({ key: "field", text: "" });
  expect(await pane.find({ type: "Text", text: /^Q3 · 3 of 3$/ })).toBeDefined();
  await pane.unmount();
  await $.command.run(RUN);
  expect(await hint($)).toContain("1 answered");

  await $.prompt.submit({ text: "something else", wait: false, origin: { kind: "composer" } });
  expect(await hint($)).toBeUndefined();
});

test("a pick list routes each item to its own next step", async ($, on) => {
  const w = world(on);
  await start($);
  await ends($, MINE);
  expect(await hint($)).toContain("Pick from 2 items");
  await $.command.run(RUN);
  const pane = await $.ui.mount({ ...PANE, surface: "desktop" });
  await pane.press({ key: "e0" });
  await pane.input({ key: "field", text: "" });
  await pane.press({ key: "e1" });
  await pane.input({ key: "field", text: "" });
  await pane.press({ key: "fill" });
  await pane.unmount();
  expect(w.box).toBe("do 1\n2 → /grill-me");
});

test("what another surface does shows here, and its reply lands in the prompt once", async ($, on) => {
  const w = world(on, "my draft");
  await start($);
  await ends($, GRILLING);
  w.hub.step(PICK_B);
  await w.clock.advance(1000);
  expect(await hint($)).toContain("1 answered");
  w.hub.deliver("Q1: B", false);
  await w.clock.advance(1000);
  expect(w.box).toBe("Q1: B\n\nmy draft");
  w.box = "";
  await w.clock.advance(1000);
  expect(w.box).toBe("");
  expect(await hint($)).toContain("1 answered");
});

test("a reply another surface sends goes as a prompt and ends the form", async ($, on) => {
  const w = world(on);
  await start($);
  await ends($, GRILLING);
  w.hub.step(PICK_B);
  w.hub.deliver("Q1: B", true);
  await w.clock.advance(1000);
  expect(w.submitted).toEqual(["Q1: B"]);
  expect(await hint($)).toBeUndefined();
});

test("without agent-hub the turn still ends and no form is offered", async ($, on) => {
  world(on, "", false);
  await start($);
  await ends($, GRILLING);
  expect(await hint($)).toBeUndefined();
});
